-- 20260101005700_dynamic_city_search.sql
-- Location selection without a hardcoded city list.
--   1. city_centroids (the existing closed lookup, NOT a new table) grows from 44 curated cities to every Indian
--      city/town in the bundled gazetteer below. The 44 curated rows keep their keys and coordinates, so every
--      existing profiles.city value, distance and test stays valid. Ambiguous names are state-qualified
--      ("Gorakhpur, Uttar Pradesh" / "Gorakhpur, Haryana"). Clients still cannot read the table directly.
--   2. search_cities(): authenticated, read-only prefix/word search that returns names and states only.
--      It reads public gazetteer data and nothing about members.
--   3. set_my_location_selection(): SAME signature. Current mode may now pass _city = NULL (or an unknown name);
--      the server then resolves the nearest gazetteer place to the snapped device position. A known city that
--      is far from the coordinates is still refused (city_mismatch). Manual mode is unchanged.
--   4. get_my_location_selection(): also returns 'state' (still never coordinates).
--   5. get_discovery_feed_page(): SAME signature/return type. When the viewer has no fresh device location
--      (manual city), distances are strictly city-centre to city-centre. Without this, a member could switch
--      between thousands of closely spaced, freely selectable town centres (manual selection is not rate
--      limited) and triangulate another member's snapped device position from the distance labels.
--
-- Gazetteer source: dr5hn/countries-states-cities-database, contributions/cities/IN.json at commit
-- c3c828d3feb7d1f9eb31b18583f91bc618b2953b (2026-10-27), licensed ODbL-1.0 (attribution required; see
-- docs/LOCATION_SELECTION.md). Coordinates are public place centres rounded to 4 decimals. Generated by
-- scripts/generate-india-gazetteer.js; do not hand-edit the VALUES block.
BEGIN;

-- ---------- 1. Gazetteer ----------
ALTER TABLE public.city_centroids
  ADD COLUMN IF NOT EXISTS state_name text CHECK (state_name IS NULL OR char_length(state_name) BETWEEN 1 AND 60),
  ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'curated' CHECK (source IN ('curated', 'gazetteer'));

UPDATE public.city_centroids c SET state_name = v.state_name
FROM (VALUES
  ('mumbai', 'Maharashtra'), ('delhi', 'Delhi'), ('bengaluru', 'Karnataka'), ('hyderabad', 'Telangana'),
  ('chennai', 'Tamil Nadu'), ('kolkata', 'West Bengal'), ('pune', 'Maharashtra'), ('jaipur', 'Rajasthan'),
