  ('patna', 'Bihar'), ('vadodara', 'Gujarat'), ('coimbatore', 'Tamil Nadu'), ('visakhapatnam', 'Andhra Pradesh'),
  ('thiruvananthapuram', 'Kerala'), ('gurugram', 'Haryana'), ('noida', 'Uttar Pradesh'),
  ('ghaziabad', 'Uttar Pradesh'), ('faridabad', 'Haryana'), ('kanpur', 'Uttar Pradesh'), ('agra', 'Uttar Pradesh'),
  ('varanasi', 'Uttar Pradesh'), ('amritsar', 'Punjab'), ('ludhiana', 'Punjab'), ('jodhpur', 'Rajasthan'),
  ('udaipur', 'Rajasthan'), ('nashik', 'Maharashtra'), ('mysuru', 'Karnataka'), ('mangaluru', 'Karnataka'),
  ('bhubaneswar', 'Odisha'), ('guwahati', 'Assam'), ('ranchi', 'Jharkhand'), ('raipur', 'Chhattisgarh'),
  ('dehradun', 'Uttarakhand'), ('panaji', 'Goa'), ('madurai', 'Tamil Nadu'), ('thane', 'Maharashtra'),
  ('navi mumbai', 'Maharashtra')
) AS v(name_key, state_name)
WHERE c.name_key = v.name_key AND c.state_name IS NULL;

