CREATE INDEX IF NOT EXISTS city_centroids_name_prefix_idx ON public.city_centroids (name_key text_pattern_ops);
CREATE INDEX IF NOT EXISTS city_centroids_lat_idx ON public.city_centroids (latitude);

-- Search-only alternative names (never stored on profiles).
CREATE TABLE IF NOT EXISTS public.city_aliases (
  alias_key text PRIMARY KEY CHECK (alias_key = public.normalize_city_key(alias_key) AND alias_key <> ''),
  name_key  text NOT NULL REFERENCES public.city_centroids (name_key) ON DELETE CASCADE
);
ALTER TABLE public.city_aliases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.city_aliases FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.city_aliases TO service_role;
